#include "HfAudioFilter.h"
#include <iostream>
#include <stdexcept>
float ratio(double hz){std::vector<float> audio(48000);for(size_t i=0;i<audio.size();++i)audio[i]=std::sin(2*3.141592653589793*hz*i/48000);HfAudioFilter f;f.process(audio,48000,true);double sum=0;for(size_t i=24000;i<audio.size();++i)sum+=audio[i]*audio[i];return std::sqrt(sum/24000)*std::sqrt(2.0);}
int main(){float low=ratio(50),voice=ratio(1000),high=ratio(8000);if(low>.08||voice<.95||high>.03)throw std::runtime_error("filter response");std::vector<float> data(2000);for(size_t i=0;i<data.size();++i)data[i]=std::sin(i*.137);auto bypass=data;HfAudioFilter off;off.process(bypass,48000,false);if(bypass!=data)throw std::runtime_error("bypass");auto whole=data;HfAudioFilter a,b;a.process(whole,48000,true);auto split=data;for(size_t start=0;start<split.size();start+=137){size_t end=std::min(split.size(),start+137);std::vector<float> chunk(split.begin()+start,split.begin()+end);b.process(chunk,48000,true);std::copy(chunk.begin(),chunk.end(),split.begin()+start);}if(split!=whole)throw std::runtime_error("chunk continuity");std::cout<<"PASS HF filter: 50Hz="<<low<<" 1kHz="<<voice<<" 8kHz="<<high<<"; exact bypass and chunk continuity\n";}
